## Algorithm 1 of Guo, Toulis & Wang (2026) -- build_perm_set() -- and the
## group property (their Proposition 2) that Theorem 1 rests on.
##
## Algorithm 1 draws a random relabelling pi of 1..n, cuts 1..n into blocks
## of K + 1 consecutive indices (a tail of n mod (K + 1) is held fixed), and
## sets psi_k = pi^{-1} o psi~_k o pi, where psi~_k shifts every block
## cyclically by k. The set {psi_0, ..., psi_K} is therefore the cyclic group
## generated by psi_1. Most assertions below are set-level, because the
## paper's own worked example orders the elements the other way round from its
## formula (discrepancy D2); the package follows the formula, which is pinned
## separately.

compose <- function(a, b) a[b]        # (a o b)(i) = a(b(i)) on image vectors
as_key <- function(G) vapply(G, paste, "", collapse = ",")
orbits <- function(g) {
  seen <- logical(length(g))
  out <- list()
  for (i in seq_along(g)) if (!seen[i]) {
    o <- i
    j <- g[i]
    while (j != i) {
      o <- c(o, j)
      j <- g[j]
    }
    seen[o] <- TRUE
    out[[length(out) + 1L]] <- sort(o)
  }
  out
}

## (n, K) grid: divisible and non-divisible n, K = 1, K + 1 = n, large K.
grid <- rbind(
  expand.grid(n = c(2, 3, 5, 6, 7, 10, 11, 12), K = 1:5),
  data.frame(n = c(20, 23, 40, 41, 250), K = c(19, 6, 39, 19, 199)))
grid <- grid[grid$K + 1 <= grid$n, ]

test_that("K + 1 elements, identity first, each a bijection of 1..n", {
  for (r in seq_len(nrow(grid))) {
    n <- grid$n[r]
    K <- grid$K[r]
    G <- build_perm_set(n, K, seed = r)
    expect_length(G, K + 1L)
    expect_identical(G[[1]], seq_len(n))
    for (g in G) expect_identical(sort(g), seq_len(n))
    expect_identical(attr(G, "block_size"), as.integer(K + 1))
  }
})

test_that("closed under composition and inverses (Proposition 2)", {
  for (r in seq_len(nrow(grid))) {
    n <- grid$n[r]
    K <- grid$K[r]
    G <- build_perm_set(n, K, seed = 100 + r)
    keys <- as_key(G)
    expect_false(anyDuplicated(keys) > 0)            # K + 1 DISTINCT elements
    comp <- unlist(lapply(G, function(a) lapply(G, function(b)
      paste(compose(a, b), collapse = ","))))
    expect_setequal(unique(comp), keys)               # closure
    inv <- vapply(G, function(g) paste(order(g), collapse = ","), "")
    expect_setequal(inv, keys)                        # inverses
  }
})

test_that("psi_k is psi_1 composed with itself k times", {
  for (r in seq_len(nrow(grid))) {
    n <- grid$n[r]
    K <- grid$K[r]
    G <- build_perm_set(n, K, seed = 200 + r)
    p <- seq_len(n)
    for (k in seq_len(K)) {
      p <- compose(G[[2]], p)
      expect_identical(G[[k + 1]], p)
    }
    expect_identical(compose(G[[2]], p), seq_len(n))   # order exactly K + 1
  }
})

test_that("every non-identity element moves (K+1) floor(n/(K+1)) indices", {
  for (r in seq_len(nrow(grid))) {
    n <- grid$n[r]
    K <- grid$K[r]
    G <- build_perm_set(n, K, seed = 300 + r)
    moved <- (K + 1) * (n %/% (K + 1))
    for (g in G[-1]) expect_identical(sum(g != seq_len(n)), as.integer(moved))
  }
})

test_that("the non-trivial orbits of psi_1 all have size K + 1", {
  for (r in seq_len(nrow(grid))) {
    n <- grid$n[r]
    K <- grid$K[r]
    o <- orbits(build_perm_set(n, K, seed = 400 + r)[[2]])
    sz <- lengths(o)
    expect_true(all(sz[sz > 1] == K + 1))
    expect_identical(sum(sz > 1), as.integer(n %/% (K + 1)))
    expect_identical(sum(sz == 1), as.integer(n %% (K + 1)))
  }
})

test_that("seeds reproduce, differ, and leave the caller's RNG alone", {
  expect_identical(build_perm_set(30, 9, seed = 7),
                   build_perm_set(30, 9, seed = 7))
  expect_false(identical(build_perm_set(30, 9, seed = 7),
                         build_perm_set(30, 9, seed = 8)))
  set.seed(123)
  before <- .Random.seed
  build_perm_set(30, 9, seed = 7)
  expect_identical(.Random.seed, before)
})

test_that("K + 1 > n, K < 1 and n < 2 are rejected", {
  expect_error(build_perm_set(5, 5, seed = 1), "exceeds n = 5")
  expect_error(build_perm_set(5, 0, seed = 1), "at least 1")
  expect_error(build_perm_set(1, 1, seed = 1), "at least 2")
})

## ---- the printed formula ---------------------------------------------------

## psi~_k from Algorithm 1's display, with the residue made 1-based,
## ((i - 1) mod (K + 1)) + 1 -- the reading under which it is a permutation.
psi_tilde <- function(n, K, k) {
  i <- seq_len(n)
  out <- i
  full <- i <= (K + 1) * (n %/% (K + 1))
  res <- ((i - 1) %% (K + 1)) + 1
  out[full] <- ifelse(res[full] <= K + 1 - k, i[full] + k,
                      i[full] - (K + 1 - k))
  out
}

test_that("each element is pi^{-1} o psi~_k o pi with the 1-based residue", {
  ## Rebuild pi the way the code draws it (sample.int(n) straight after
  ## set.seed(seed)) and compare element by element: the package follows the
  ## formula, so element k + 1 is psi_k, not psi_{K+1-k}.
  for (r in seq_len(nrow(grid))) {
    n <- grid$n[r]
    K <- grid$K[r]
    s <- 500 + r
    pi_vec <- with_seed(s, sample.int(n))
    pi_inv <- order(pi_vec)
    G <- build_perm_set(n, K, seed = s)
    for (k in 0:K)
      expect_identical(G[[k + 1]], pi_inv[psi_tilde(n, K, k)[pi_vec]])
  }
})

test_that("Algorithm 1 as printed, with 'i mod (K+1)' read literally", {
  skip_discrepancy("D1", paste("Algorithm 1 prints 'i mod (K+1)', which read",
             "as the 0-based residue maps index K+1 of every block into the",
             "next block (not a permutation)"))
  n <- 6
  K <- 2
  i <- seq_len(n)
  for (k in 1:K) {
    lit <- ifelse(i %% (K + 1) <= K + 1 - k, i + k, i - (K + 1 - k))
    expect_identical(sort(lit), i)                     # fails: 2 3 4 5 6 7
  }
})

test_that("Algorithm 1's worked example S_1^k as the image of psi~_k", {
  skip_discrepancy("D2", paste("the worked example lists S_1^k = (K+2-k, ...,",
             "K+1, 1, ..., K+1-k) as the images of psi~_k, which is the",
             "INVERSE of the displayed formula; the sets agree, the element",
             "order does not"))
  n <- 8
  K <- 3
  for (k in 1:K) {
    example <- c((K + 2 - k):(K + 1), seq_len(K + 1 - k))
    expect_identical(psi_tilde(n, K, k)[1:(K + 1)], example)
  }
})

test_that("the paper's worked example is the same SET as the formula", {
  ## The two conventions differ only by k <-> K + 1 - k, i.e. by inversion,
  ## so the group itself is unaffected (what validity needs).
  n <- 12
  K <- 3
  formula <- lapply(0:K, function(k) psi_tilde(n, K, k))
  example <- lapply(0:K, function(k) order(psi_tilde(n, K, k)))
  expect_setequal(as_key(example), as_key(formula))
})

## ---- the JSS draft's Section 3.6 example -----------------------------------

test_that("draft Sec. 3.6: build_perm_set(n = 6, K = 2, seed = 1) as printed", {
  G <- build_perm_set(n = 6, K = 2, seed = 1)
  expect_identical(G[[1]], 1:6)
  expect_identical(G[[2]], c(5L, 6L, 1L, 2L, 3L, 4L))
  expect_identical(G[[3]], c(3L, 4L, 5L, 6L, 1L, 2L))
  expect_identical(attr(G, "block_size"), 3L)
  ## block_size is K + 1: the block length in RELABELLED coordinates, and the
  ## group order. The blocks act on pi^{-1}({1,2,3}) and pi^{-1}({4,5,6}).
  pi_vec <- with_seed(1, sample.int(6))
  expect_setequal(lapply(orbits(G[[2]]), sort),
                  list(sort(which(pi_vec %in% 1:3)),
                       sort(which(pi_vec %in% 4:6))))
  expect_setequal(orbits(G[[2]]), list(c(1L, 3L, 5L), c(2L, 4L, 6L)))
})

test_that("draft Sec. 3.6 prose: blocks {1,2,3}, {4,5,6} under the identity", {
  skip_discrepancy("D3", paste("draft Sec. 3.6 says the seed = 1 relabelling is",
             "the identity and the shifted blocks are {1,2,3} and {4,5,6};",
             "the printed element 5 6 1 2 3 4 has orbits {1,3,5}, {2,4,6}",
             "(pi = 1 4 3 6 2 5)"))
  G <- build_perm_set(n = 6, K = 2, seed = 1)
  expect_setequal(orbits(G[[2]]), list(1:3, 4:6))
})
